{
"css": "/* Day Tabs (E2) */
.day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 26px;
}

.day-tabs button {
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  border-radius: 16px;
  border: 1px solid #e8e8e8;
  background-color: #ffffff;
  color: #111111;
  font-weight: 700;
  font-size: 14px;
  line-height: 1;
  cursor: default;
  transition: none;
}

/* Selected State (aria-pressed="true") */
.day-tabs button[aria-pressed="true"] {
  background-color: #111111;
  color: #ffffff;
  border-color: #111111;
}

/* Disabled State */
.day-tabs button:disabled {
  opacity: 1; /* Explicitly preserve as per contract */
}"
}
